from review import card,save,DATE
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2470';_,c=card(i);refs=c['references'];refs[0]['locator']='DISC 2023, article 22: distributed model in Section 1, oriented-coloring definition and the complete question and footnote 3 on page 22:13 read. Target is proper O(β^{2−ε}) coloring in f(β)+O(log* n) rounds.'
refs.append(dict(id='greedy2026',title='Greedy-Like Defective Coloring: Distributed Algorithms and Applications',authors='Marc Fuchs, Fabian Kuhn',year=2026,url='https://arxiv.org/abs/2608.02386',locator='August 2026 preprint: communication model, Theorem 2.1 and “List Coloring with Bounded Outdegree” discussion read. Communication is bidirectional despite input orientations; new list guarantees still require quadratic-order lists in β.'))
save(i,dict(title='Breaking the quadratic color bound for bounded outdegree',formal='Do there exist a constant ε∈(0,1], constants C₁,C₂>0, a computable function f:ℕ₊→ℕ₊ and one deterministic LOCAL algorithm that, for every n-vertex graph supplied with an orientation of maximum outdegree at most β≥1, computes a proper vertex coloring using at most ⌈C₁β^{2−ε}⌉ colors within f(β)+C₂log* n rounds?',definitions='The communication network is a finite undirected simple graph G=(V,E), |V|=n≥2. Every edge has a supplied direction, known to its endpoints; no acyclicity is promised. A vertex’s outdegree is its number of outgoing edges, and every vertex has outdegree at most the supplied bound β. Its indegree and total degree may be arbitrarily large. A proper coloring assigns each vertex a label from one common palette so that endpoints of every edge have different labels, regardless of the edge direction. Vertices execute the same deterministic algorithm in synchronous rounds, have unique identifiers of O(log n) bits, know their incident ports and edge directions, and may know n and β. Each round allows a separate message of unbounded size to each neighbor in either direction and unrestricted finite local computation. Cost is worst-case round count over graphs, orientations and identifiers. No precomputed coloring or graph decomposition is supplied. The function f may grow arbitrarily fast with β, but cannot depend on n, total degree or the orientation’s path lengths. Both the exponent improvement ε and the coefficient of log* n must be uniform over β and n. Here log* n is the number of repeated base-two logarithms needed to reach a value at most one. Edgeless graphs, including the β=0 case, can be assigned one color separately.',question_type='yes_no',answer_criterion='Prove the existence of the uniform deterministic algorithm with the stated palette and additive round bound, or establish that no such ε, constants, computable f and algorithm exist. A palette reduction by only logarithmic factors, a runtime depending on total degree, or a multiplicative log n term does not establish this claim.',context_blocks=[b('Outdegree is the available sparsity guarantee','The orientation controls how many edges leave a vertex, not how many neighbors it has. Thus a fast coloring theorem parameterized by maximum total degree cannot simply replace β here.'),b('Quadratically many colors are already very local','Linial’s result, as recalled in the source, gives O(β²) colors in O(log* n) rounds. The question asks for a fixed positive reduction in the exponent while allowing extra time depending only on β.', 'primary'),b('Existence of few colors does not give the desired round bound','Graphs with this orientation admit O(β)-colorings. The source records an O(β)-coloring algorithm with a multiplicative logarithmic dependence on n, which misses the requested additive f(β)+O(log* n) regime.', 'primary'),b('Recent list-coloring progress keeps the quadratic scale','The August 2026 preprint obtains stronger oriented list-defective guarantees and a proper-list-coloring result with lists of size β²+β+1. That does not provide the subquadratic exponent asked for here.', 'greedy2026')],why='Would cross a basic locality barrier for coloring sparse oriented networks, making fewer colors achievable without paying global-size-dependent time beyond log* n.',references=refs,progress=[dict(date='2023',text='The source isolates subquadratic proper coloring in f(β)+O(log* n) rounds as open, despite advances in list and defective variants.',citation='primary'),dict(date='2026-08',text='New oriented list-defective results include proper list coloring at quadratic list size; they do not give the requested fixed exponent improvement.',citation='greedy2026')],status='source_open',status_note='The complete source question, deterministic LOCAL conventions and August 2026 oriented-list theorem were checked. Later searches did not locate the stated uniform subquadratic palette guarantee through 12 September 2026.',model_self_contained=True,requires_context=False,importance=imp(c,'A fundamental locality-versus-palette question under an outdegree bound.'),review_note='Recovered the missing β^{2−ε} target and additive runtime. Defined bidirectional LOCAL communication, input orientation, uniform constants and unrestricted indegree; removed list-defective method advice.',working_summary=sm(['The network comes with an orientation having at most β outgoing edges at every vertex.','A deterministic distributed algorithm can already color it with O(β²) colors in O(log* n) rounds.','The question is whether β² can be replaced by β^{2−ε} for one fixed ε>0.','Additional time may depend arbitrarily on β, but the dependence on n must remain additive O(log* n).','New results for list and defective colorings have not supplied this proper-coloring guarantee.'],['primary','greedy2026'])),notes=['Recovered the truncated palette and round-complexity target.','Defined the input orientation, proper coloring and bidirectional LOCAL model.','Separated outdegree from total degree and made parameter-uniform constants explicit.','Checked August 2026 progress without conflating list or defective variants.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2304.09666'])

i='TCS-2489';_,c=card(i);refs=c['references'];refs[0]['locator']='ITCS 2023, article 27: #Sub definition, Theorem 3/Table 1 and Section 5 “Arbitrary Pattern Graphs” read. The host class remains monotone and somewhere dense; the hereditary restriction to be removed is on the pattern class.'
refs.append(dict(id='journal2024',title='Counting Subgraphs in Somewhere Dense Graphs',authors='Marco Bressan, Leslie Ann Goldberg, Kitty Meeks, Marc Roth',year=2024,url='https://doi.org/10.1137/22M1535668',pdf_url='https://arxiv.org/pdf/2209.03402',locator='SIAM Journal on Computing 53(5), 1409–1438. Full arXiv v3, 12 April 2024, final outlook page 29 repeats the arbitrary-pattern/monotone-host characterization question. Journal bibliographic details checked on the authors’ university pages.'))
issue='The source requests an “explicit combinatorial” necessary-and-sufficient criterion but proposes neither a predicate nor a formal class of admissible criteria. It also does not state effective-presentation assumptions for the newly unrestricted pattern classes. The structural criterion and class-effectivity conventions must be specified before this becomes one fully quantified binary benchmark; no invented invariant or unconditional FPT/#W[1] dichotomy is asserted.'
save(i,dict(title='Characterizing countable patterns in monotone somewhere-dense hosts',formal='Is there an explicit combinatorial characterization of the pairs (ℋ,𝒢) for which exact subgraph counting #Sub(ℋ→𝒢), parameterized by the number of pattern vertices, is fixed-parameter tractable, when 𝒢 is monotone and somewhere dense but ℋ is an arbitrary graph class? The source asks to remove closure restrictions on the pattern class; it does not supply the desired criterion or its formal admissibility conditions.',definitions='All graphs are finite, undirected and simple. The classes ℋ of patterns and 𝒢 of hosts are fixed for a counting problem; an input is a pair of explicitly represented graphs H∈ℋ and G∈𝒢, promised to belong to those classes. The parameter is k=|V(H)|. The output Sub(H,G) is the number of subgraphs of G isomorphic to H, not necessarily induced. Equivalently it is the number of injective maps V(H)→V(G) preserving every edge of H, divided by the number of automorphisms of H. Extra edges of G between image vertices need not be included in the counted subgraph. An automorphism is a vertex permutation preserving adjacency. Fixed-parameter tractability means an exact deterministic algorithm with runtime f(k)N^c for a computable f and a constant c, where N is the explicit input length. The algorithm, f and c may depend on the fixed pair of classes, but c cannot depend on k. Class membership is a promise, not part of the counting task. A host class is monotone if it is closed under deleting vertices and edges. It is somewhere dense if some fixed r≥0 has the property that, for every t, some graph in the class has K_t as an r-shallow minor: there are t pairwise disjoint connected vertex sets of radius at most r with an edge between every pair, whose contractions yield a clique after extra edges are discarded. A class is hereditary if it is closed under induced subgraphs. The source’s existing #Sub classification assumes hereditary ℋ; this question drops that assumption on ℋ while retaining monotonicity of 𝒢. The forbidden subgraphs of 𝒢 are the graphs not contained as subgraphs in any host in 𝒢; the sought criterion may depend on these host restrictions as well as on ℋ.',question_type='yes_no',answer_criterion='Give a precisely defined combinatorial condition on the two classes and prove that it is equivalent to fixed-parameter tractability in the stated setting, with its effectivity and complexity assumptions explicit. The source’s phrase “explicit combinatorial” still needs a formal admissibility convention. A classification only for hereditary patterns, a particular bounded-degeneracy host family, or one fixed finite pattern does not cover the requested scope.',context_blocks=[b('The small pattern varies with the input','For any one fixed pattern, brute force already gives a polynomial-time algorithm. The question asks when all patterns in an unbounded family can be handled with one exponent independent of pattern size.'),b('Both classes influence tractability','Restricting the host can eliminate patterns entirely or change which embeddings must be counted. The criterion therefore cannot be inferred from the pattern class alone.', 'primary'),b('The source handles hereditary patterns','Its classification covers hereditary pattern classes paired with monotone host classes. The remaining question asks how the characterization changes when patterns need not be closed under taking induced subgraphs.', 'primary'),b('The fuller publication retains the question','The April 2024 full version again asks for a combinatorial description for arbitrary pattern classes and monotone somewhere-dense host classes. It is a classification request, with no proposed invariant to test.', 'journal2024'),b('What still requires specification',issue)],why='Would explain the joint structural sources of parameterized tractability in exact subgraph counting across a broad class of sparse and dense host restrictions.',references=refs,progress=[dict(date='2023',text='The source classifies hereditary pattern classes with monotone hosts and asks to extend the classification to arbitrary patterns.',citation='primary'),dict(date='2024',text='The full version associated with the journal publication preserves the arbitrary-pattern characterization question.',citation='journal2024')],status='source_open',status_note='Conference definitions and classification table, the April 2024 full-version outlook and journal publication details were checked. Later searches, including the MFCS 2026 abstract on bounded-degeneracy space complexity, did not locate a general characterization through 12 September 2026. The criterion itself remains unspecified.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the exact counting task and which closure restriction is being removed; no candidate criterion is invented.']),importance=imp(c,'A broad structural classification problem for parameterized exact subgraph counting.'),review_note='Defined exact non-induced counts and the pattern-size parameter, preserved monotone somewhere-dense hosts, and separated arbitrary pattern classes from the distinct hereditary-host question.',working_summary=sm(['Count copies of a small input pattern inside a host graph, allowing extra edges between the copied vertices.','The goal is a structural criterion for runtime f(pattern size) times a polynomial with fixed exponent.','Hosts remain closed under subgraphs and somewhere dense, while the pattern class may be arbitrary.','The source already classifies hereditary pattern classes and asks to remove that restriction.','It does not propose the criterion or fully specify what counts as an explicit combinatorial characterization.'],['primary','journal2024'])),notes=['Recovered the arbitrary-pattern, monotone-host scope and exact non-induced counting task.','Defined FPT with pattern size as parameter and clarified fixed classes versus input graphs.','Checked the full 2024 outlook and later bounded-degeneracy work.','Retained the unspecified criterion and effectivity conventions.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2209.03402','https://www.cs.ox.ac.uk/people/leslieann.goldberg/publications.html','https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.MFCS.2026.28'],state='improved_unfinished')
